import { createEvolu } from '@evolu/common';
import { evoluSvelteDeps } from '@evolu/svelte';
import { Schema } from './datastructure';

export const evolu = createEvolu(evoluSvelteDeps)(Schema, {
	syncUrl: '',
	name: 'dummy_codename_dashboard20',

	initialData: (instance) => {

	},
	logger: {
		level: 'off'
	},
	indexes: (createIndex) => [
		createIndex('nodeDataIdPair').on('nodeData').columns(['nodeId', 'subId']).unique()
	]
});

evolu.subscribeError(() => {
	const error = evolu.getError();
	console.error('Evolu error:', error);
});
